function splitAcrossCards(text, count) {
  const sentences = text.match(/[^.!?。！？]+(?:[.!?。！？]+|$)/gu)?.map((sentence) => sentence.trim()).filter(Boolean) || [];
  const chunks = Array.from({ length: count }, () => []);
  sentences.forEach((sentence, index) => {
    const chunkIndex = Math.min(count - 1, Math.floor((index * count) / Math.max(sentences.length, 1)));
    chunks[chunkIndex].push(sentence);
  });
  return chunks.map((chunk) => chunk.join(" "));
}

function researchBlock(lang, key) {
  const r = pageResearch[lang][key];
  const additions = splitAcrossCards(`${pageParityBoost[lang][key]} ${pageParityTail[lang][key]}`.trim(), r.points.length);
  return `<section class="section research-panel"><div class="section-head"><div><p class="kicker">${esc(r.kicker)}</p><h2>${esc(r.title)}</h2></div><p>${esc(r.intro)}</p></div><div class="evidence-cards">${r.points.map(([title, text], index) => `<article><span>0${index + 1}</span><h3>${esc(title)}</h3><p>${esc(`${text} ${additions[index]}`.trim())}</p></article>`).join("")}</div></section>`;
}

