function scripts() {
  return `<script>
  const menu=document.querySelector('.menu-button');if(menu){menu.addEventListener('click',()=>{const h=document.querySelector('.topbar');h.classList.toggle('open');menu.setAttribute('aria-expanded',h.classList.contains('open')?'true':'false')})}
  document.querySelectorAll('[data-query]').forEach((button)=>button.addEventListener('click',()=>{const input=document.querySelector('#site-search');input.value=button.dataset.query;input.focus()}));
  const localSearch=document.querySelector('#product-grid');const input=document.querySelector('#site-search');if(localSearch&&input){input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();let visible=0;document.querySelectorAll('.product-card').forEach((card)=>{const show=!q||card.dataset.search.includes(q);card.hidden=!show;if(show)visible++});document.querySelector('.empty-state').hidden=visible!==0})}
  document.querySelectorAll('[data-filter]').forEach((button)=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.classList.remove('active'));button.classList.add('active');const q=button.dataset.filter;let visible=0;document.querySelectorAll('.product-card').forEach((card)=>{const show=q==='all'||card.dataset.search.includes(q);card.hidden=!show;if(show)visible++});document.querySelector('.empty-state').hidden=visible!==0}));
  </script>`;
}

function renderPage(path, lang) {
  const t = languages[lang];
  const c = copy[lang];
  const cc = categoryCopy[lang];
  const staticPaths = new Set(["/", "/categories", "/finds", "/qc-guide", "/shipping", "/articles", "/faq", "/privacy", "/terms"]);
  const articleSlug = path.startsWith("/articles/") ? path.slice("/articles/".length) : null;
  const article = articleSlug ? seoArticles[lang].find((item) => item.slug === articleSlug) : null;
  const categorySlug = path.startsWith("/categories/") ? path.slice("/categories/".length) : null;
  const categoryIndex = categorySlug ? categories.findIndex((item) => item.slug === categorySlug) : -1;
  if (!staticPaths.has(path) && !article && categoryIndex < 0) return null;
  let content;
  if (path === "/") content = home(lang, t);
  else if (path === "/categories") content = categoriesPage(lang);
  else if (categoryIndex >= 0) content = categoryPage(lang, categorySlug);
  else if (path === "/finds") content = findsPage(lang, t);
  else if (path === "/qc-guide") content = qcGuide(lang);
  else if (path === "/shipping") content = shippingPage(lang);
  else if (path === "/articles") content = articlesPage(lang);
  else if (article) content = articlePage(lang, articleSlug);
  else if (path === "/faq") content = faqPage(lang);
  else if (path === "/privacy" || path === "/terms") content = legalPage(path.slice(1), lang);
  const meta = article ? [article.title, article.description] : categoryIndex >= 0 ? [cc.names[categoryIndex], cc.descriptions[categoryIndex]] : {
    "/": [t.heading.replace("\n", " "), t.sub],
    "/categories": [cc.title, cc.intro],
    "/finds": [c.findsPage.title, c.findsPage.intro],
    "/qc-guide": [c.qc.title, c.qc.intro],
    "/shipping": [c.shipping.title, c.shipping.intro],
    "/articles": [c.articlesPage.title, c.articlesPage.intro],
    "/faq": [c.faqTitle, c.faqIntro],
    "/privacy": [c.legal.privacy, c.legal.privacyIntro],
    "/terms": [c.legal.terms, c.legal.termsIntro],
  }[path];
  const [title, description] = meta;
  const homeTitles = {
    en: "FindQC Store — Source-Matched Product Finds & Listing Checks",
    de: "FindQC Store — Quellengenaue Produktfunde & Angebotsprüfung",
    es: "FindQC Store — Productos con fuente exacta y revisión de fichas",
    fr: "FindQC Store — Produits reliés à leur source et contrôle des fiches",
    it: "FindQC Store — Prodotti con fonte esatta e controllo schede",
  };
  const documentTitle = path === "/" ? homeTitles[lang] : `${title} — FindQC Store`;
  const robots = path === "/privacy" || path === "/terms" ? "noindex,follow" : "index,follow,max-image-preview:large";
  const alternates = Object.keys(languages).map((code) => `<link rel="alternate" hreflang="${code}" href="${ORIGIN}${localizedPath(code, path)}" />`).join("") + `<link rel="alternate" hreflang="x-default" href="${ORIGIN}${localizedPath("en", path)}" />`;
  const structuredData = pageSchemas(path, lang, title, categoryIndex);
  return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(documentTitle)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="${robots}"><link rel="canonical" href="${ORIGIN}${localizedPath(lang, path)}">${alternates}<meta name="theme-color" content="#f6efe5">${structuredData}${styles()}<script async src="https://www.googletagmanager.com/gtag/js?id=G-PHLMLCFBBH"></script><script>window.dataLayer = window.dataLayer || [];function gtag(){dataLayer.push(arguments);}gtag("js", new Date());gtag("config", "G-PHLMLCFBBH");</script></head><body class="${path === "/" ? "home-shell" : ""}">${nav(lang, path, t)}${content}${footer(lang, t)}${scripts()}</body></html>`;
}

function sitemap() {
  const paths = ["/", "/categories", ...categories.map((category) => `/categories/${category.slug}`), "/finds", "/qc-guide", "/shipping", "/articles", ...seoArticles.en.map((article) => `/articles/${article.slug}`), "/faq"];
  const urls = Object.keys(languages).flatMap((lang) => paths.map((path) => `<url><loc>${ORIGIN}${localizedPath(lang, path)}</loc><lastmod>2026-08-28</lastmod></url>`)).join("");
  return `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls}</urlset>`;
}

export default {
  async fetch(request) {
    try {
      const url = new URL(request.url);
      const canonicalPath = url.pathname.length > 1 ? url.pathname.replace(/\/+$/, "") : url.pathname;
      if (url.protocol !== "https:" || url.hostname !== "findqcs.store" || canonicalPath !== url.pathname) return Response.redirect(`${ORIGIN}${canonicalPath}${url.search}`, 301);
      if (url.pathname === "/robots.txt") return new Response(`User-agent: *\nAllow: /\n\nSitemap: ${ORIGIN}/sitemap.xml\n`, { headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "public, max-age=3600" } });
      if (url.pathname === "/sitemap.xml") return new Response(sitemap(), { headers: { "content-type": "application/xml; charset=utf-8", "cache-control": "public, max-age=3600" } });
      const { lang, path } = parsePath(url.pathname);
      const html = renderPage(path, lang);
      if (!html) return new Response("Not Found", { status: 404, headers: { "content-type": "text/plain; charset=utf-8", "x-robots-tag": "noindex, nofollow" } });
      return new Response(html, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300", "x-content-type-options": "nosniff", "referrer-policy": "strict-origin-when-cross-origin", "x-frame-options": "SAMEORIGIN" } });
    } catch (error) {
      console.error(JSON.stringify({ event: "render_error", message: error instanceof Error ? error.message : String(error) }));
      return new Response("Temporary service error", { status: 500, headers: { "content-type": "text/plain; charset=utf-8", "x-robots-tag": "noindex, nofollow" } });
    }
  },
};
